import {validateCustomRubric} from './template-library.mjs';
/**
 * Anonymised teacher-entered observation records. No diagnosis, learner identity,
 * grading decision, or learner-level AI inference is generated by this module.
 */
import {escapeHtml, totalPoints} from './core.mjs';
import {rubricPoints,validateRubricRatings,criterionDescription} from './rubrics.mjs';
export const SUPPORT_OPTIONS=Object.freeze([
 ['none','Destek belirtilmedi'],['independent','Bağımsız yanıt'],
 ['verbal','Sözel ipucu'],['visual','Görsel destek'],
 ['material','Somut materyal'],['other','Diğer / öğretmen açıklaması']
]);
const acceptedSupport=new Set(SUPPORT_OPTIONS.map(([value])=>value));
const round2=n=>Math.round((n+Number.EPSILON)*100)/100;
const text=(x,max)=>String(x??'').slice(0,max).trim();
/** This checksum is only a local mismatch detector; never a security digest. */
export function examFingerprint(exam){
 const s=JSON.stringify({title:exam.title,subject:exam.subject,grade:exam.grade,objective:exam.objective,instruction:exam.instruction,adaptations:exam.adaptations,
  questions:(exam.questions||[]).map(q=>[q.id,q.type,q.prompt,q.simplifiedPrompt,q.objective,q.points,q.options,q.answer,q.pairs,q.visualNote,q.visualDots,q.visualStyle,q.visualAltText,q.visualMode,q.numberLineStart,q.numberLineEnd])});
 let h=2166136261;
 for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);}
 return (h>>>0).toString(16).padStart(8,'0');
}
export function createAssessment(exam,{id,code}={}){
 if(!Array.isArray(exam?.questions))throw new Error('Değerlendirme için sınav gerekli.');
 const key=text(id||`oturum-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,70);
 return {format:'bep-evaluation',schemaVersion:1,id:key,code:text(code||'Anonim Oturum',70),fingerprint:examFingerprint(exam),
  createdAt:new Date().toISOString(),entries:exam.questions.map(q=>({questionId:q.id,pointsAwarded:null,support:'none',observation:'',scoringMode:'manual',rubricRatings:{},rubricTemplate:null})),
  overallNote:''};
}
export function isCompatible(exam,assessment){return Boolean(assessment?.fingerprint===examFingerprint(exam) && Array.isArray(assessment.entries)
  &&assessment.entries.length===exam.questions.length&&assessment.entries.every((e,i)=>e.questionId===exam.questions[i].id));}
export function normaliseAssessment(raw,exam){
 if(!raw||raw.format!=='bep-evaluation'||raw.schemaVersion!==1||typeof raw.id!=='string'||raw.id.length>70||!Array.isArray(raw.entries))throw new Error('Değerlendirme dosyası geçersiz.');
 if(!isCompatible(exam,raw))throw new Error('Değerlendirme farklı veya sonradan değiştirilmiş bir sınava ait.');
 const entries=raw.entries.map((e,i)=>{
  if(!e||e.questionId!==exam.questions[i].id)throw new Error('Soru eşleşmesi geçersiz.');
  const score=e.pointsAwarded===null||e.pointsAwarded===''?null:Number(e.pointsAwarded),maximum=Number(exam.questions[i].points);
  if(score!==null&&(!Number.isFinite(score)||score<0||score>maximum||round2(score)!==score))throw new Error(`${i+1}. soru için puan geçersiz.`);
  if(!acceptedSupport.has(e.support))throw new Error(`${i+1}. soru için destek kaydı geçersiz.`);
  if(typeof e.observation!=='string'||e.observation.length>500)throw new Error(`${i+1}. sorunun gözlem notu sınırı aşıldı.`);
  const scoringMode=e.scoringMode??'manual';
  if(!['manual','rubric'].includes(scoringMode))throw new Error(`${i+1}. soru için puanlama yöntemi geçersiz.`);
  const rubricRatings=e.rubricRatings??{};
  const rubricTemplate=e.rubricTemplate==null?null:validateCustomRubric(e.rubricTemplate);
  validateRubricRatings(exam.questions[i].type,rubricRatings,scoringMode==='rubric'?rubricTemplate:null);
  if(scoringMode==='rubric'&&rubricPoints(exam.questions[i],rubricRatings,rubricTemplate)!==score)throw new Error(`${i+1}. rubrik puanı ile sonuç uyuşmuyor.`);
  return {questionId:e.questionId,pointsAwarded:score,support:e.support,observation:e.observation,scoringMode,rubricRatings,rubricTemplate};
 });
 if(typeof raw.code!=='string'||raw.code.length>70||typeof raw.overallNote!=='string'||raw.overallNote.length>800)throw new Error('Değerlendirme metin sınırı aşıldı.');
 return {format:'bep-evaluation',schemaVersion:1,id:raw.id,code:raw.code,fingerprint:raw.fingerprint,
  createdAt:typeof raw.createdAt==='string'?raw.createdAt.slice(0,50):'',entries,overallNote:raw.overallNote};
}
export function evaluationSummary(exam,assessment){
 if(!isCompatible(exam,assessment))return {compatible:false,assessed:0,unassessed:exam.questions?.length||0,awarded:0,assessedMax:0,possible:totalPoints(exam),ratio:null,coverage:[]};
 const coverage=new Map();let assessed=0,awarded=0,assessedMax=0;
 exam.questions.forEach((q,i)=>{
  const e=assessment.entries[i],answered=e.pointsAwarded!==null,key=text(q.objective||'Kazanım belirtilmedi',500);
  if(!coverage.has(key))coverage.set(key,{objective:key,questionCount:0,assessed:0,points:0,assessedMax:0,possible:0});
  const c=coverage.get(key);c.questionCount++;c.possible+=Number(q.points)||0;
  if(answered){assessed++;awarded+=e.pointsAwarded;assessedMax+=Number(q.points)||0;c.assessed++;c.points+=e.pointsAwarded;c.assessedMax+=Number(q.points)||0;}
 });
 return {compatible:true,assessed,unassessed:exam.questions.length-assessed,awarded:round2(awarded),assessedMax:round2(assessedMax),possible:totalPoints(exam),
  ratio:assessedMax?round2(100*awarded/assessedMax):null,coverage:[...coverage.values()].map(c=>({...c,points:round2(c.points),assessedMax:round2(c.assessedMax),ratio:c.assessedMax?round2(100*c.points/c.assessedMax):null}))};
}
function csvCell(x){
 let s=String(x??'');
 // Defuse spreadsheet formula execution, including leading whitespace and control characters.
 if(/^[\s\u0000-\u001f]*[=+@-]/.test(s))s="'"+s;
 return `"${s.replace(/"/g,'""')}"`;
}
export function evaluationCsv(exam,assessment){
 const a=normaliseAssessment(assessment,exam),summary=evaluationSummary(exam,a);
 const header=['Oturum kodu','Soru','Kazanım','Azami puan','Verilen puan','Durum','Destek','Gözlem','Puanlama yöntemi','Rubrik ölçütleri'];
 const lines=[header];
 exam.questions.forEach((q,i)=>{const e=a.entries[i];lines.push([a.code,i+1,q.objective,q.points,e.pointsAwarded===null?'':e.pointsAwarded,e.pointsAwarded===null?'Değerlendirilmedi':'Değerlendirildi',SUPPORT_OPTIONS.find(([k])=>k===e.support)?.[1],e.observation,e.scoringMode==='rubric'?'Ölçütlü rubrik':'Elle puanlama',e.scoringMode==='rubric'?criterionDescription(q,e.rubricRatings,e.rubricTemplate):'']);});
 lines.push(['GENEL TOPLAM','','',summary.possible,summary.awarded,`${summary.assessed}/${exam.questions.length} soru`,'','']);
 return '\ufeff'+lines.map(row=>row.map(csvCell).join(';')).join('\r\n');
}
export function evaluationPrintable(exam,assessment){
 const a=normaliseAssessment(assessment,exam),summary=evaluationSummary(exam,a),safe=escapeHtml;
 const rows=exam.questions.map((q,i)=>{const e=a.entries[i];return `<tr><td>${i+1}</td><td>${safe(q.objective||'—')}</td><td>${e.pointsAwarded===null?'—':`${e.pointsAwarded} / ${q.points}`}</td><td>${safe(SUPPORT_OPTIONS.find(([k])=>k===e.support)?.[1]||'—')}</td><td>${safe(e.observation||'—')}<div style="font-size:10px;color:#666">${e.scoringMode==='rubric'?safe('Rubrik · '+criterionDescription(q,e.rubricRatings,e.rubricTemplate)):'Elle puanlama'}</div></td></tr>`;}).join('');
 const objectiveRows=summary.coverage.map(c=>`<tr><td>${safe(c.objective)}</td><td>${c.assessed}/${c.questionCount}</td><td>${c.points} / ${c.assessedMax}</td><td>${c.ratio===null?'—':c.ratio+'%'}</td></tr>`).join('');
 return `<!doctype html><html lang="tr"><head><meta charset="utf-8"/><title>Değerlendirme · ${safe(exam.title)}</title><style>
 @page{size:A4;margin:18mm}*{box-sizing:border-box}body{font:12px/1.6 Arial,sans-serif;color:#20242e;margin:0}header{border-top:7px solid #c50e1f;padding:16px 0 12px;border-bottom:1px solid #bbb}h1{font-size:21px;margin:2px 0;color:#111}h2{font-size:14px;margin:24px 0 7px;color:#9e1120}.stamp{font-size:10px;color:#9e1120;text-transform:uppercase;font-weight:bold;letter-spacing:1px}.meta{display:flex;gap:25px;flex-wrap:wrap;margin:12px 0 18px}table{width:100%;border-collapse:collapse;margin:8px 0 20px}td,th{border:1px solid #c9cdd3;padding:8px;text-align:left;vertical-align:top;overflow-wrap:anywhere}th{background:#f4f4f6;font-size:10px}tr{break-inside:avoid}.question-table th:first-child,.question-table td:first-child{width:34px;white-space:nowrap}.question-table th:nth-child(3),.question-table td:nth-child(3){width:100px;white-space:nowrap}.question-table th:nth-child(4){width:115px}.note{border:1px solid #dedfe4;background:#f9f9fa;padding:10px;white-space:pre-wrap}.small{font-size:10px;color:#666}@media print{header{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body><header><div class="stamp">DOU tasarım teması · Öğretmen değerlendirme taslağı</div><h1>${safe(exam.title)}</h1><span>${safe(exam.subject)} · ${safe(exam.grade)}</span></header>
 <div class="meta"><span><b>Anonim oturum:</b> ${safe(a.code)}</span><span><b>Değerlendirilen:</b> ${summary.assessed}/${exam.questions.length}</span><span><b>İşlenen puan:</b> ${summary.awarded}/${summary.assessedMax}</span></div><p class="small">Puan yüzdesi sadece değerlendirilen sorular üzerinden hesaplanır. Değerlendirilmemiş sorular sıfır değildir. BEP hedeflerine ilişkin pedagojik kararlar öğretmene aittir.</p>
 <h2>Soru bazlı kayıt</h2><p class="small">— : Henüz değerlendirilmedi (0 puan değildir).</p><table class="question-table"><thead><tr><th>No</th><th>Kazanım</th><th>Puan</th><th>Kullanılan destek</th><th>Gözlem</th></tr></thead><tbody>${rows}</tbody></table>
 <h2>Kazanım bazlı özet</h2><table><thead><tr><th>Kazanım</th><th>Değerlendirilen soru</th><th>İşlenen puan</th><th>Oran</th></tr></thead><tbody>${objectiveRows}</tbody></table><h2>Öğretmen notu</h2><div class="note">${safe(a.overallNote||'Henüz genel gözlem notu girilmedi.')}</div><p class="small">Bu belge anonim bir pilot değerlendirme kaydıdır; tıbbi tanı veya resmî yeterlik kararı değildir. Gerçek öğrencilerin kimlik/sağlık bilgilerini girmeyin.</p></body></html>`;
}
